function count(dna, k){ dna=String(dna).toUpperCase().replace(/[^ACGT]/g,''); var m={};
  for(var i=0;i+k<=dna.length;i++){ var s=dna.slice(i,i+k); m[s]=(m[s]||0)+1; } return m; }
function topK(dna, k, n){ var m=count(dna,k); var a=Object.keys(m).map(function(k2){return [k2,m[k2]];});
  a.sort(function(x,y){return y[1]-x[1]|| (x[0]<y[0]?-1:1);}); return a.slice(0,(n||a.length)); }
var EXPORTS={count:count, topK:topK};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.KmerForgePure = EXPORTS; }
